import sys

def count_intervals(n, m, x):
    if n == 0 and x == 1:
        return 1
    count = 0
    for r1 in range(1, m + 1):
        for r2 in range(r1, m + 1):
            if r2 - r1 > 1:
                count += COMB(n - 1, r1 - 1) * COMB(n + r1 - r2 - 1, n - 1)
                count %= 1000000007
    return count

def COMB(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k == 1 or k == n - 1:
        return n
    temp = 1
    for k in range(2, n + 1):
        temp *= k
        temp %= 1000000007
    temp *= pow(n - k + 1, 1, 1000000007)
    temp %= 1000000007
    temp *= pow(k, -1, 1000000007)
    temp %= 1000000007
    return temp

