def is_non_collinear(a, b, c):
    x1, y1 = a
    x2, y2 = b
    x3, y3 = c
    return (y2 - y1) * (x3 - x1) != (y3 - y1) * (x2 - x1)

def has_antipodal_points(a, b, c):
    x1, y1 = a
    x2, y2 = b
    x3, y3 = c
    if x1-y1 == 0:
        if x2-x1 == 0:
            return False
    else:
        if y2-y1 != 0:
            m1 = (x3-x1)/(y3-y1)
            m2 = (x1-x2)/(y1-y2)
            return m2 == 1/m1
    return False

def count_holy_triplets(n, points):
    count = 0
    for i in range(n):
        j = i + 1
        while j < n:
            k = j + 1
            while k < n:
                if is_non_collinear(points[i], points[j], points[k]) and has_antipodal_points(points[i], points[j], points[k]):
                    count += 1
                k += 1
            j += 1
    return count

