def reconstruct_tree(n, edges):
    # Convert question marks to strings of length n
    for i in range(n - 1):
        edge = edges[i]
        for j in range(len(edge)):
            edge = edge.replace("?", "C")
            if len(edge) > n:
                return -1
        edges[i] = edge

    # Check the connectivity of the edges
    connected = [False] * n
    for i in range(n - 1):
        for j in range(i + 1, n - 1):
            if edge[i] == edge[j]:
                connected[i], connected[j] = True, True
    if connected.count(True) != n - 1:
        return -1

    # Find the starting point
    start = -1
    edge_length = {edge[0]: i for i, edge in enumerate(edges)}
    for edge in edges:
        if len(edge) > 1:
            if edge[0] not in edge_length:
                start = edge_length[edge[1]] + 1
            elif edge[1] not in edge_length:
                start = edge_length[edge[0]]
            else:
                return -1

    # Build the tree
    trees = [[-1] * 2 for _ in range(n)]
    if start >= 0:
        trees[0][0], trees[0][1] = edge[edge_length[start]][0], start
        for j in range(1, n - 1):
            trees[j][0], i = edge[edge_length[trees[j][0]]][0], trees[j][1]
            trees[j][1] = edge[edge_length[trees[j][1]]][1]
            while i != j - 1:
                trees[i][0], trees[i][1] = edge[edge_length[trees[i][0]]][0], trees[i][1]
                i = trees[i][0]
    else:
        return -1

    return "\n".join(f"{m} {n}" for m, n in ((m, trees[m][0]) for m in range(n - 1)))

