    """Computes the factorial of n modulo 1000000007."""
    result = 1
    for i in range(1, n + 1):
        result = result * i % 1000000007
    return result

def get_fibo(n):
    """Returns [fibo(n), fibo(n-1)]."""
    factors = [1, 1, 1, 0]
    for count, num in enumerate(range(0, n)):
        if num != 0:
            factors[count + 1] = (factors[count] + facts[count - 1] * (num if num else 1)) % 1000000007
            factors[count] = (factors[count - 1] if count > 1 else 1) * (num if num else 1) % 1000000007
