def factorize(n):
    i = 1
    factors = []
    while i * i <= n:
        if n % i == 0:
            factors.append(i)
            powers = factorize(n // i)
            for power in powers:
                factors.append(power)
            factors.append(n // i)
            break
        i += 1
    return factors

def generalized_sharo(n, m):
    factors = factorize(n * m)
    result = 1
    for p in factors:
        result = (result * pow(p, n // (i:=factorize(m)[factors[::-1].index(i)] + 1) % 1000000007)) % 1000000007
