def find_min_buses(distance, bus_routes, start, destination):
    n = len(distance)

    # Build a directed graph and edges per bus route
    road_graph = defaultdict(list)
    routes_with_start = {}
    for u, v in bus_routes:
        road_graph[u].append(v)
        routes_with_start.setdefault(u, []).append((v, u))

    # Simulate the journeys
    journey_distances = [float('inf')] * n
    journey_distances[start] = 0
    while journey_distances[destination] == float('inf'):
        min_dis = float('inf')
        min_point = None
        for i in range(n):
            if journey_distances[i] + min_dis < min_dis:
                min_dis = journey_distances[i] + min_dis
                min_point = i
        min_dis += 1  # Increment penalty for deviation
        if min_point == destination:
            return min_dis
        for neigh in road_graph[min_point]:
            if journey_distances[neigh] > journey_distances[min_point] + 1:
                journey_distances[neigh] = journey_distances[min_point] + 1
                heapq.heappush(routes_with_start[neigh], (-journey_distances[neigh], -neigh))

    # Check for route not found or less than min_dis steps
    for route in routes_with_start.get(destination, []):
        if journey_distances[destination] + 1 > min_dis:
            return -1
    return min_dis

