import itertools

def find_minimum_height(matrix, area):
    """
    Find the minimum height in a rectangular area of a height matrix.
    """
    min_height = min(min(row) for row in matrix[area[0]-1:area[2]])
    return min_height

def compute_area_height(matrix, area, current_height):
    """
    Compute the height difference from current area to minimum height.
    """
    return current_height - find_minimum_height(matrix, (area[0], area[1], area[2]))

def construct_cities(area, map_matrix):
    """
    Construct cities from the optimal position and then build them on it.
    """
    cities = set()  # Default set to store cities

    while any(area[0] < n for n in area):
        # Find the optimal site
        min_heights = []
        for left in range(min(area[1], area[3])):
            for top in range(min(area[0], area[2])):
                min_heights.append(compute_area_height(map_matrix, (top+1, left+1, top+area[2], left+area[3]), map_matrix[top+1][left+1]))
            for top in range(max(area[0], area[2]), max(area[3], area[1]) + 1):
                min_heights.append(compute_area_height(map_matrix, (top+1, left+1, top+area[2], left+area[3]), map_matrix[top+1][left+1]))
        min_height = min(min_heights)
        sites = [(top+1, left+1, min_height)]  # for building
        if any((top, left) in [a for a in cities] for top, left in sites):
            continue
        while max(area[0], area[2]) < min(area[0], area[2]) + max(area[3], area[1]):
            top = max(area[0], area[2])
            left = max(area[1], area[3])
            min_height = min_heights.pop()
            if compute_area_height(map_matrix, (top+1, left+1, top+area[2], left+area[3]), map_matrix[top+1][left+1]) == min_heights.pop():
                sites.append((top+1, left+1, min_height))
        areas = [sum((s[2] for s in row)) > 0 for row in zip(*[range(0, len(area))]*4)]
        if any(areas):
            area = tuple(row[2: len(row)+2] for row in sites[::(-1, 1)])
    return cities

def validate_area(area, map_matrix):
    """
    Validate if the next site's position is valid.
    """
    for top in range(area[0], area[2] + 1):
        for left in range(area[1], area[3] + 1):
            if map_matrix[top][left]:
                return False
    return True

def process_input():
    n, m, a, b = map(int, input().split())
    map_matrix = []
    for i in range(n):
        row = list(map(int, input().split()))
        map_matrix.append(row)
    cities = construct_cities([(1, 1, b, a), (n//2, m//2, b, a)], map_matrix)
    return len(cities), [f'{top} {left} {height}' for line in cities for top, left, height in line]

