def largestPrimeFactor(n: int) -> int:
    i = 2
    largestPrime = 1
    while i * i <= n:
        if n % i:
            i += 1
        else:
            while n % i == 0:
                n //= i
            largestPrime = i
        if n == 1:
            return largestPrime
    return largestPrime if n > 1 else largestPrime

def coordinatesToVector(p1: List[int], p2: List[int]) -> List[float]:
    return [p2[0] - p1[0], p2[1] - p1[1]]

def findGCD(list1: List[int], list2: List[int]) -> int:
    return list1[0] * list1[1] // gcd(list1[0], abs(list1[1]))

def onCircle(P1: List[int], P2: List[int], P3: List[int]) -> bool:
    vector1 = coordinatesToVector(P1, P2)
    vector2 = coordinatesToVector(P1, P3)
    return findGCD(vector1, vector2) == 1 or findGCD(vector1, coordinatesToVector(P2, P3)) == 1 or findGCD(vector1, vector2) == 1

def countHolyTriplets(n: int, points: List[List[int]]) -> int:
    A = [(points[i][1] - points[0][1]) for i in range(1, n)]
    B = [(points[i][0] - points[0][0]) for i in range(1, n)]
    det = sum(A[i] * B[i] for i in range(n)) % (2**32)  # determinant of CABA
    inverseOfAverager = pow(gcd(det, 2), -1, 2**32)  # inverse of prev*
    hts = (det * inverseOfAverager) % (2**32)
    return (det if hts < 0 else det % 2) // 2

