def calculate_sum(order: dict, l: int, r: int) -> int:
    prev = -1
    current_sum = 0
    for i, num in enumerate(range(l, r+1), 1):
        if i >= len(order):
            break
        current_sum += pre_compute(current_sum, prev, i)
        prev = num
    return current_sum % (10**9 + 7)

def pre_compute(current_sum: int, prev: int, index: int) -> int:
    return (current_sum + (max(2**4, 2**7) if index == len(order) else order[index] - prev) * pre_compute(current_sum + (1 if index == 1 else 0), order[index], index + 1)) % (10**9 + 7)

