        p = top_ones(bin(n), n) % mod if bin(n).count('1') >= max(i, 2) else Q_00[n]
        for k in range(1, n):
            p = (modular_permutation(k, n, mod) - q) % mod
        return p if n != 2 else max(0, (p - q + mod) % mod)
    Q_1 = modular_permutation(1, bit_length(n)-1, mod)
    Q_pos = [Q_1]
    Q_00 = [Q_1]
    for i in range(2, bit_length(n)):
        Q_nom = Q_pos[-1] * top_ones(2**(i), n) % mod
        Q_den = 2**i % mod
        Q_1i = (Q_nom % mod - mod // Q_den * Q_00[-1] % mod) % mod
        Q_pos.append(Q_1i)
        Q_00.append(Q_1i * Q_pos[-1] % mod)

    def top_ones(n, maxv):
        if maxv < n:
            return top_ones(n, n+n)
        tmp = int(math.log(int(maxv), 2))
        v = ((1 << tmp) * top_ones(n>>tmp)) % mod
        p = int(1 << (n - tmp - 1))
        v = (v - p) % mod
        return v
    return Q_1 % mod

