from heapq import heappush, heappop
from bisect import bisect_left

def minimize_hours(n, k, tokens):
    # Heaps for regions's tokens and the maximum achieved level in each region
    regions = [0] * k
    greater_than = [float('-inf')] * k

    result = 0.0
    total_hours = 0.0

    for token in tokens:
        total_hours += 1  # Adding one hour per token even if already done

        if not regions[0]:
            total_hours += 1e-10
            regions[0] = token
            heappush(regions, -token)
            greater_than[regions[0]] = token
            result += region_achievement(token)

        level_index = bisect_left(greater_than, token)
        for i in range(level_index, k):
            if regions[i] <= token:
                regions[i] = token
                greater_than[regions[i]] = token
                result += region_achievement(token)
                break

            if not regions[regions[i]]:
                greater_than[regions[i]] = token

        regions.sort()

    return total_hours * 2.0, result + k - 1

def region_achievement(level):
    current_level = regions[0]

    if current_level == level:
        return region_score(len(greater_than), level)
    else:
        placed = bisect_left(greater_than, level) + 1

        smallest = min(greater_than[placed:i] for i in range(placed, k))

        if current_level > smallest:
            return region_score(placed, level) + len(greater_than) - placed + 1
        elif current_level > greater_than[placed]:
            return region_score(placed, level)

def region_score(start_index, level):
    score = sum(token * count
            for token, count in zip(region_search(start_index), region_counts(start_index, k))
            if token <= level)
    return start_index + 1 + score / k

def region_search(start_index):
    return region_search(start_index) + greater_than[start_index: -1 + k + 1]

def region_search(start_index):
    result = []
    for value in region_counts(start_index, k):
        if value > 0:
            c = dict(result)
            c[value] = c.get(value, 0) + 1
            result = c.values()
    return sorted(result)

def region_counts(start_index, k):
    return (region_counts(start_index) + 1) ** 2 for k in range(k))

