def is_non_collinear(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0

def is_antipodal(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    return max(abs(x1 - x2), abs(x1 - x3), abs(y1 - y2), abs(y1 - y3)) == min(abs(x1 - x2), abs(x1 - x3), abs(y1 - y2), abs(y1 - y3))

def count_holy_triplets(n, points):
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if j != k and not is_non_collinear(points[i], points[j], points[k]):
                    continue
                if is_antipodal(points[i], points[j], points[k]):
                    count += 1
    return count

