def factorial(n):
    fact = 1
    for i in range(1, n + 1):
        fact *= i
    return fact

mod = 10**9 + 7

def combinations(n, r):
    return (factorial(n) // (factorial(n - r) * factorial(r)))

def lattice_paths(m, n):
    return (factorial(2 * m) * pow(factorial(n), -1, mod) // pow(factorial(m), -1, mod)) % mod

def count_ways(n, m, x):
    if n == 1:
        return 0 if x <= m else pow(factorial(m) * pow(factorial(x), -1, mod) // pow(factorial(m - x), -1, mod), mod - 2, mod)
    total = 0
    for i in range(x, m + 1):
        total = (total + lattice_paths(n - 1, i) * combinations(n - 2, n - 1)) % mod
    return total

n, m, x = map(int, input().split())
print(count_ways(n, m, x))
