import math
from functools import lru_cache

MOD = 10**9 + 7

@lru_cache(maxsize=None)
def count_ways(n, k):
    if n == 1:
        return 1
    if n == 2:
        return 1
    if k >= n:
        return 0
    return (count_ways(n-2, k-1) + (k-1) * count_ways(n-2, k)) % MOD

def calculate_sequences(n, k):
    result = [0] * (k + 1)
    for j in range(1, k + 1):
        result[j] = count_ways(n, j)
    for i in range(1, k):
        result[i] = (result[i] * (2 * i + 1)) % MOD
    return result

n, k = map(int, input().split())
sequences = calculate_sequences(n, k)
print(' '.join(map(str, sequences)))
